  if (R.phase === 'race' && me.st === 'grid' && R.t > 0.15) S.whip();
  if (me.st !== 'run') return;
  S.drive(me, dt);
  if (me.warn && me.warn.t > 0.4 && Math.abs(me.d - me.warn.by.d) < 7.6 && window.__dodge) { me.u = me.warn.sg; me.b = 0; }
